1	import { Block, Text } from "@prototyp/skeletor";
2	import type { NativeStackScreenProps } from "@react-navigation/native-stack";
3	import { FlashList } from "@shopify/flash-list";
4	import type { EventTimelineItem } from "@unomed/react-native-matrix-sdk";
5	import { useAtomValue } from "jotai";
6	import { TimelineAtoms } from "modules/timeline/jotai";
7	import { type FC, useEffect, useState } from "react";
8	import { StyleSheet } from "react-native";
9	import { SingleMessageType } from "screens/room/fragments";
10	import { GoBackHeader, Loading } from "shared/components";
11	import { ScreenLayout } from "shared/components/screen-layout/ScreenLayout";
12	import { Colors, TextSize } from "shared/styles";
13	
14	const keyExtractor = (item: EventTimelineItem) => {
15	  const eventId = item.eventOrTransactionId;
16	  if (eventId?.tag === "EventId") {
17	    return eventId.inner.eventId;
18	  }
19	  if (eventId?.tag === "TransactionId") {
20	    return eventId.inner.transactionId;
21	  }
22	  return String(item.timestamp);
23	};
24	
25	export const PinnedEvents: FC<
26	  NativeStackScreenProps<Routes, "pinnedEvents">
27	> = ({ route }) => {
28	  const { room } = route.params;
29	  const pinnedEventIds = useAtomValue(TimelineAtoms.pinnedEventIds);
30	  const [events, setEvents] = useState<EventTimelineItem[]>([]);
31	  const [loading, setLoading] = useState(true);
32	
33	  useEffect(() => {
34	    if (!room) return;
35	
36	    setEvents([]);
37	
38	    const initPinnedTimeline = async () => {
39	      try {
40	        if (pinnedEventIds.length === 0) {
41	          setEvents([]);
42	          setLoading(false);
43	          return;
44	        }
45	
46	        const timeline = await room.timeline();
47	        const fetchedEvents: EventTimelineItem[] = [];
48	
49	        for (const id of pinnedEventIds) {
50	          try {
51	            await timeline.fetchDetailsForEvent(id);
52	            const item = await timeline.getEventTimelineItemByEventId(id);
53	            if (item) {
54	              fetchedEvents.push(item);
55	            }
56	          } catch (error) {
57	            console.warn("Failed to load pinned event:", id, error);
58	          }
59	        }
60	
61	        setEvents(fetchedEvents);
62	        setLoading(false);
63	      } catch (error) {
64	        console.error("Failed to initialize pinned events timeline:", error);
65	        setLoading(false);
66	      }
67	    };
68	
69	    initPinnedTimeline();
70	
71	    return () => {};
72	  }, [room]);
73	
74	  return (
75	    <ScreenLayout type="modal">
76	      <GoBackHeader title="Pinned Events" margins={{ marginBottom: 20 }} />
77	      <FlashList
78	        data={events}
79	        renderItem={({ item }) => {
80	          return (
81	            <Block paddings={{ paddingHorizontal: 16 }}>
82	              <SingleMessageType
83	                roomId={room.id()}
84	                event={item}
85	                isPreviousSameSender={false}
86	              />
87	            </Block>
88	          );
89	        }}
90	        keyExtractor={keyExtractor}
91	        contentContainerStyle={styles.listContent}
92	        ListEmptyComponent={
93	          <Block align="center" justify="center" flex={1} paddings={40}>
94	            {loading ? (
95	              <Loading isFullScreen={false} />
96	            ) : (
97	              <Text size={TextSize.medium} color={Colors.white50}>
98	                No pinned events
99	              </Text>
100	            )}
101	          </Block>
102	        }
103	        showsVerticalScrollIndicator={false}
104	      />
105	    </ScreenLayout>
106	  );
107	};
108	
109	const styles = StyleSheet.create({
110	  listContent: {
111	    flexGrow: 1,
112	    paddingBottom: 20,
113	  },
114	});
