25	export class TimelineService {
26	  public static sendMessage = async (
27	    roomId: string,
28	    message: string,
29	    mentions?: Mentions,
30	    htmlBody?: string,
31	  ) => {
32	    const room = MatrixCore.getRoom(roomId);
33	    const timeline = await room.timeline();
34	    if (!timeline) throw new Error("Timeline not found");
35	    let messageContent = htmlBody
36	      ? messageEventContentFromHtml(message, htmlBody)
37	      : messageEventContentFromMarkdown(message);
38	    if (mentions) messageContent = messageContent.withMentions(mentions);
39	    await timeline.send(messageContent);
40	  };
41	
42	  public static replyToMessage = async (
43	    roomId: string,
44	    message: string,
45	    eventId: string,
46	    mentions?: Mentions,
47	    htmlBody?: string,
48	  ) => {
49	    const room = MatrixCore.getRoom(roomId);
50	    const timeline = await room.timeline();
51	    if (!timeline) throw new Error("Timeline not found");
52	    let messageContent = htmlBody
53	      ? messageEventContentFromHtml(message, htmlBody)
54	      : messageEventContentFromMarkdown(message);
55	    if (mentions) messageContent = messageContent.withMentions(mentions);
56	    await timeline.sendReply(messageContent, eventId);
57	  };
58	
59	  public static editMessage = async (
60	    roomId: string,
61	    event: EventTimelineItem,
62	    message: string,
63	    mentions?: Mentions,
64	    htmlBody?: string,
65	  ) => {
66	    const room = MatrixCore.getRoom(roomId);
67	    const timeline = await room.timeline();
68	    if (!timeline) throw new Error("Timeline not found");
69	
70	    if (!event.eventOrTransactionId) {
71	      throw new Error("Event is missing event or transaction id");
72	    }
73	
74	    let messageContent = htmlBody
75	      ? messageEventContentFromHtml(message, htmlBody)
76	      : messageEventContentFromMarkdown(message);
77	    if (mentions) messageContent = messageContent.withMentions(mentions);
78	
79	    const editedContent = EditedContent.RoomMessage.new({
80	      content: messageContent,
81	    });
82	    await timeline.edit(event.eventOrTransactionId, editedContent);
83	  };
84	
85	  public static reportMessage = async (
86	    roomId: string,
87	    event: EventTimelineItem,
88	    reason: string,
89	  ) => {
90	    const room = MatrixCore.getRoom(roomId);
91	    const eventId = getEventId(event);
92	    if (!eventId) throw new Error("Event is missing event id");
93	    await room.reportContent(eventId, undefined, reason);
94	  };
95	
96	  public static deleteMessage = async (
97	    roomId: string,
98	    event: EventTimelineItem,
99	  ) => {
100	    const room = MatrixCore.getRoom(roomId);
101	    const eventId = getEventId(event);
102	    if (!eventId) throw new Error("Event is missing event id");
103	    await room.redact(eventId, undefined);
104	  };
105	
106	  public static forwardMessage = async (
107	    roomId: string,
108	    event: EventTimelineItem,
109	    messageType: ForwardMessageType,
110	  ) => {
111	    const client = MatrixCore.getClient();
112	    const room = MatrixCore.getRoom(roomId);
113	    const timeline = await room.timeline();
114	    if (!timeline) throw new Error("Timeline not found");
115	
116	    if (messageType === "text") {
117	      const textContent = this.getTextContent(event);
