16	export const RoomInfoMessage: FC<Props> = ({ event }) => {
17	  const senderId = event.sender;
18	
19	  const content = () => {
20	    if (event.content.tag === TimelineItemContent_Tags.State) {
21	      const tag = event.content.inner.content.tag;
22	
23	      if (tag === OtherState_Tags.RoomName) {
24	        return `${senderId} changed the room name to ${event.content.inner.content.inner.name}`;
25	      }
26	      if (tag === OtherState_Tags.RoomTopic) {
27	        return `${senderId} changed the room topic to "${event.content.inner.content.inner.topic}"`;
28	      }
29	      if (tag === OtherState_Tags.RoomAvatar) {
30	        return `${senderId} changed the room avatar`;
31	      }
32	      if (tag === OtherState_Tags.RoomEncryption) {
33	        return `${senderId} changed the room encryption state`;
34	      }
35	      if (tag === OtherState_Tags.RoomJoinRules) {
36	        return `${senderId} changed the room join rules to ${event.content.inner.content.inner.joinRule?.tag}`;
37	      }
38	      if (tag === OtherState_Tags.RoomHistoryVisibility) {
39	        return `${senderId} changed the room history visibility to ${event.content.inner.content.inner.historyVisibility?.tag}`;
40	      }
41	      if (tag === OtherState_Tags.RoomGuestAccess) {
42	        return `${senderId} changed the room guest access`;
43	      }
44	      if (tag === OtherState_Tags.RoomPowerLevels) {
45	        return `${senderId} changed the room power levels`;
46	      }
47	      if (tag === OtherState_Tags.RoomCreate) {
48	        return `${senderId} created the room`;
49	      }
50	      if (tag === OtherState_Tags.PolicyRuleRoom) {
51	        return `${senderId} changed the room policy rule`;
52	      }
53	      if (tag === OtherState_Tags.RoomPinnedEvents) {
54	        if (event.content.inner.content.inner.change) {
55	          return `${senderId} unpinned an event`;
56	        }
57	        return `${senderId} pinned an event`;
58	      }
59	
60	      return null;
61	    }
62	  };
63	
64	  if (!content()) return null;
65	
66	  return (
67	    <Block align="center" margins={{ marginTop: 16, marginHorizontal: "auto" }}>
68	      <Block
69	        paddings={8}
70	        background="transparent"
71	        border={{
72	          borderRadius: 16,
73	        }}
74	        flexDirection="row"
75	        gap={{
76	          row: 4,
77	          col: 16,
78	        }}
79	        align="center"
80	        flex={{ flexWrap: "wrap" }}
81	      >
